# Parse the graph and build adjacency list
edges_text = context.split("The graph has the following edges:")[1].split("Operation:")[0].strip()

adj = {}
for line in edges_text.strip().split('\n'):
    if '->' in line:
        parts = line.split('->')
        src = parts[0].strip()
        dst = parts[1].strip()
        if src not in adj:
            adj[src] = []
        adj[src].append(dst)

print("Adjacency list:")
for k, v in adj.items():
    print(f"{k}: {v}")

print("\nStarting BFS from eccbc87e4b")
start = "eccbc87e4b"

# BFS to find nodes at exactly depth 2
from collections import deque

visited = {start: 0}  # node -> depth
queue = deque([start])
depth2_nodes = set()

while queue:
    node = queue.popleft()
    current_depth = visited[node]

    if node in adj:
        for neighbor in adj[node]:
            if neighbor not in visited:
                visited[neighbor] = current_depth + 1
                queue.append(neighbor)
                if current_depth + 1 == 2:
                    depth2_nodes.add(neighbor)

print(f"\nVisited nodes with depths: {visited}")
print(f"\nNodes at exactly depth 2: {sorted(depth2_nodes)}")
